'use strict';
// Campanhas complementares. O editor e a execução continuam sendo os das missões originais.
const arenaStep=(title,story,task,starter,expected,requires,hint,analogy)=>({
  title,en:title,story,storyEn:story,task,taskEn:task,starter,expected,requires,
  hint,hintEn:hint,analogy,analogyEn:analogy
});
MISSIONS.push(
  {id:'arena-logica',title:'Central de lógica',en:'Logic center',summary:'Decisões, laços, texto e métodos em situações de sala de aula.',summaryEn:'Decisions, loops, text and methods.',icon:'code',color:'#e39a47',steps:[
    arenaStep('Boletim da turma','A secretaria quer saber quem passou.','Percorra as notas {4, 7, 9} com for e imprima Reprovado, Aprovado, Aprovado, em linhas separadas.',missionWrap('    int[] notas = {4, 7, 9};\n    // Percorra as notas e use if/else.'),'Reprovado\nAprovado\nAprovado',/\bfor\s*\([\s\S]*\bif\s*\(/,['Use um for para visitar cada nota.','A aprovação começa em 6.','Dentro do for, use if (nota >= 6).'],'Cada nota passa pelo mesmo portão de decisão.'),
    arenaStep('Contador de pares','Um evento distribui senhas de 1 a 8.','Conte quantas senhas de 1 a 8 são pares com um laço e imprima Pares: 4.',missionWrap('    int pares = 0;\n    // Percorra de 1 a 8 e conte os pares.'),'Pares: 4',/\bfor\s*\([\s\S]*%\s*2/,['Percorra os números de 1 a 8.','Um número par deixa resto zero ao dividir por 2.','Faça pares++ quando i % 2 == 0.'],'O contador recebe uma ficha para cada senha par.'),
    arenaStep('Nome ao contrário','A turma prepara etiquetas de trás para frente.','Inverta a String "JAVA" usando charAt em um laço e imprima AVAJ.',missionWrap('    String palavra = "JAVA";\n    String invertida = "";\n    // Percorra os índices do último para o primeiro.'),'AVAJ',/\bfor\s*\([\s\S]*charAt\s*\(/,['Comece em palavra.length() - 1.','Reduza o índice até zero.','Concatene palavra.charAt(i) em invertida.'],'Ler de trás para frente é percorrer as cadeiras da última à primeira.'),
    arenaStep('Taxa com método','Um serviço cobra R$ 2 por quilômetro.','Crie static int calcular(int km) que devolva km * 2. Imprima Taxa: 6 e Taxa: 10 usando calcular(3) e calcular(5).','public class Main {\n  public static void main(String[] args) {\n    // Imprima o resultado de calcular(3) e calcular(5).\n  }\n  // Crie calcular(int km) aqui.\n}','Taxa: 6\nTaxa: 10',/\bstatic\s+int\s+calcular\s*\(/,['O método recebe um int e devolve um int.','Faça return km * 2.','Chame calcular(3) e calcular(5) nos dois println.'],'Um método é uma receita reutilizada para pedidos diferentes.')
  ]},
  {id:'arena-poo',title:'Oficina de objetos',en:'Object workshop',summary:'Encapsulamento, construtores, herança e polimorfismo.',summaryEn:'Encapsulation, constructors, inheritance and polymorphism.',icon:'boxes',color:'#a373d7',steps:[
    arenaStep('Aluno encapsulado','O boletim precisa guardar o nome sem expor o campo.','Crie class Aluno com private String nome, construtor e getNome(). Instancie Ana e imprima Aluna: Ana.','class Aluno {\n  // Campo privado, construtor e getNome()\n}\npublic class Main {\n  public static void main(String[] args) {\n    // Crie Aluno("Ana") e imprima seu nome.\n  }\n}','Aluna: Ana',/\bprivate\s+String\s+nome\b[\s\S]*\bgetNome\s*\(/,['Guarde nome como private String.','No construtor, use this.nome = nome.','getNome() retorna nome; imprima "Aluna: " + aluno.getNome().'],'O campo privado fica em uma gaveta aberta apenas por métodos.'),
    arenaStep('Conta com regra','Um depósito negativo não deve alterar o saldo.','Crie Conta com saldo inicial 10, método depositar(int valor) que aceita apenas valores positivos. Teste -5 e 7; imprima Saldo: 17.','class Conta {\n  private int saldo = 10;\n  // Crie depositar(int valor) e getSaldo().\n}\npublic class Main {\n  public static void main(String[] args) {\n    // Teste os dois depósitos e imprima o saldo.\n  }\n}','Saldo: 17',/\bprivate\s+int\s+saldo\b[\s\S]*\bif\s*\(/,['Valide valor > 0 antes de somar.','Some ao saldo somente quando a condição for verdadeira.','Use getSaldo() para exibir o resultado.'],'Encapsular permite colocar um segurança na porta do saldo.'),
    arenaStep('Herança de mensagens','Uma notificação urgente personaliza sua mensagem.','Crie classe Aviso com texto(), e Urgente extends Aviso sobrescrevendo texto() para retornar "Urgente!". Imprima esse texto.','class Aviso { String texto() { return "Aviso"; } }\nclass Urgente extends Aviso {\n  // Sobrescreva texto().\n}\npublic class Main {\n  public static void main(String[] args) {\n    Aviso aviso = new Urgente();\n    System.out.println(aviso.texto());\n  }\n}','Urgente!',/\bextends\s+Aviso\b[\s\S]*\bString\s+texto\s*\(/,['Mantenha a assinatura String texto().','Em Urgente, devolva "Urgente!".','O objeto real é Urgente, mesmo guardado em Aviso.'],'A classe filha reaproveita a base e muda a fala quando precisa.'),
    arenaStep('Polimorfismo da turma','Dois perfis se apresentam de maneiras diferentes.','Crie Professor e Estudante extends Pessoa, cada um sobrescrevendo papel(). Percorra Pessoa[] e imprima Professor e Estudante.','class Pessoa { String papel() { return "Pessoa"; } }\nclass Professor extends Pessoa { /* sobrescreva papel() */ }\nclass Estudante extends Pessoa { /* sobrescreva papel() */ }\npublic class Main {\n  public static void main(String[] args) {\n    Pessoa[] turma = {new Professor(), new Estudante()};\n    // Percorra e imprima papel() de cada pessoa.\n  }\n}','Professor\nEstudante',/\bextends\s+Pessoa\b[\s\S]*\bfor\s*\(/,['As duas subclasses implementam papel().','Use um for ou for-each para percorrer turma.','Chame pessoa.papel() dentro do laço.'],'A mesma pergunta recebe respostas próprias de cada objeto.')
  ]},
  {id:'arena-colecoes',title:'Dados da turma',en:'Classroom data',summary:'Listas, mapas, conjuntos e ordenação.',summaryEn:'Lists, maps, sets and sorting.',icon:'layers',color:'#48a9a1',steps:[
    arenaStep('Lista de presença','Três pessoas confirmaram presença.','Use ArrayList<String> para guardar Ana, Bia, Caio. Remova Bia e imprima Ana e Caio, um por linha.','import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    List<String> nomes = new ArrayList<>();\n    // Adicione, remova e percorra.\n  }\n}','Ana\nCaio',/\bArrayList\s*<[\s\S]*\.remove\s*\(/,['Adicione os três nomes com add.','Remova "Bia" com remove.','Use for-each para imprimir quem ficou.'],'A lista é uma fila da qual você pode retirar um nome.'),
    arenaStep('Pontos por equipe','Ana marcou 7 pontos e Bia marcou 5.','Use Map<String,Integer> para guardar as pontuações e imprima Ana: 7 e Bia: 5.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    Map<String,Integer> pontos = new HashMap<>();\n    // Adicione e consulte as duas chaves.\n  }\n}','Ana: 7\nBia: 5',/\bHashMap\s*<[\s\S]*\.get\s*\(/,['Adicione pares com put.','Busque cada nome com get.','Imprima explicitamente Ana e depois Bia para manter a ordem.'],'O mapa é uma agenda: cada nome aponta para seus pontos.'),
    arenaStep('E-mails sem repetição','A lista contém dois registros iguais.','Use HashSet<String> para adicionar a@exemplo.com duas vezes e b@exemplo.com uma vez. Imprima Únicos: 2.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    Set<String> emails = new HashSet<>();\n    // Adicione os três registros.\n  }\n}','Únicos: 2',/\bHashSet\s*<[\s\S]*\.size\s*\(/,['HashSet ignora valores repetidos.','Use add três vezes.','Use size() após as inserções.'],'O conjunto não deixa o mesmo convite entrar duas vezes.'),
    arenaStep('Ranking ordenado','Três notas estão fora de ordem.','Guarde 8, 3 e 5 em uma List<Integer>, use Collections.sort e imprima 3, 5 e 8 em linhas separadas.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    List<Integer> notas = new ArrayList<>(Arrays.asList(8, 3, 5));\n    // Ordene e percorra.\n  }\n}','3\n5\n8',/\bCollections\.sort\s*\(/,['Collections.sort modifica a lista.','Depois da ordenação, percorra as notas.','Use System.out.println em cada elemento.'],'Ordenar é colocar os números em uma fila do menor ao maior.')
  ]},
  {id:'arena-excecoes',title:'Código resistente',en:'Resilient code',summary:'Entradas inválidas, exceções e recursos fechados.',summaryEn:'Invalid input, exceptions and resource safety.',icon:'route',color:'#d98072',steps:[
    arenaStep('Número inválido','Uma pessoa digitou 12 e outra digitou "doze".','Percorra {"12","doze"}; use try/catch para imprimir 12 e Inválido, em linhas separadas.', 'public class Main {\n  public static void main(String[] args) {\n    String[] entradas = {"12", "doze"};\n    // Parseie cada valor com tratamento de exceção.\n  }\n}','12\nInválido',/\btry\s*\{[\s\S]*\bcatch\s*\(\s*NumberFormatException/,['Use Integer.parseInt dentro do try.','Capture NumberFormatException.','No catch, imprima "Inválido".'],'Uma entrada ruim recebe explicação, sem derrubar o programa.'),
    arenaStep('Divisão segura','Um relatório pode ter denominador zero.','Teste 12/3 e 12/0 com try/catch de ArithmeticException. Imprima 4 e Divisão impossível.', 'public class Main {\n  public static void main(String[] args) {\n    int[] divisores = {3, 0};\n    // Trate a divisão em cada volta.\n  }\n}','4\nDivisão impossível',/\btry\s*\{[\s\S]*\bcatch\s*\(\s*ArithmeticException/,['Percorra os dois divisores.','No try, imprima 12 / divisor.','No catch, imprima "Divisão impossível".'],'O tratamento impede que uma conta inválida pare as outras.'),
    arenaStep('Índice protegido','Uma consulta pede posições 1 e 5 de um array pequeno.','Use try/catch de ArrayIndexOutOfBoundsException para imprimir 20 e Fora do intervalo.', 'public class Main {\n  public static void main(String[] args) {\n    int[] valores = {10, 20, 30};\n    int[] indices = {1, 5};\n    // Acesse com proteção.\n  }\n}','20\nFora do intervalo',/\bcatch\s*\(\s*ArrayIndexOutOfBoundsException/,['Percorra indices.','No try, imprima valores[indice].','Capture a exceção e imprima "Fora do intervalo".'],'A proteção avisa quando alguém pede uma cadeira que não existe.'),
    arenaStep('Leitor com fechamento','Um texto em memória tem duas linhas.','Use BufferedReader com try-with-resources e StringReader para imprimir Java e Seguro, uma linha por vez.', 'import java.io.*;\npublic class Main {\n  public static void main(String[] args) throws IOException {\n    String texto = "Java\\nSeguro";\n    // Abra BufferedReader com try-with-resources.\n  }\n}','Java\nSeguro',/\btry\s*\(\s*BufferedReader/,['Use new BufferedReader(new StringReader(texto)).','No try, leia duas linhas com readLine().','Imprima cada linha; o recurso fecha automaticamente.'],'É como devolver a chave da biblioteca ao terminar.')
  ]},
  {id:'arena-moderno',title:'Java moderno',en:'Modern Java',summary:'Lambda, Stream, Optional e comparadores.',summaryEn:'Lambda, Stream, Optional and comparators.',icon:'spark',color:'#6985d9',steps:[
    arenaStep('Filtrar pares','Uma lista tem números de 1 a 6.','Use stream().filter para selecionar pares e forEach para imprimir 2, 4 e 6 em linhas separadas.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    List<Integer> numeros = Arrays.asList(1, 2, 3, 4, 5, 6);\n    // Crie o pipeline.\n  }\n}','2\n4\n6',/\.stream\s*\(\s*\)[\s\S]*\.filter\s*\(/,['Use n -> n % 2 == 0.','filter seleciona; forEach imprime.','Use System.out::println como ação terminal.'],'O filtro é uma peneira que deixa passar só os pares.'),
    arenaStep('Dobrar valores','Uma equipe quer ver o dobro de 2, 3 e 4.','Use stream().map(n -> n * 2) e imprima 4, 6, 8, um por linha.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    List<Integer> valores = Arrays.asList(2, 3, 4);\n    // Transforme e imprima.\n  }\n}','4\n6\n8',/\.stream\s*\(\s*\)[\s\S]*\.map\s*\(/,['map transforma cada item.','Passe uma lambda n -> n * 2.','Finalize com forEach(System.out::println).'],'Cada item entra em uma máquina de dobrar.'),
    arenaStep('Nome opcional','O cadastro pode não ter apelido.','Use Optional.ofNullable(null) com orElse("Visitante") e imprima Olá, Visitante.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    String apelido = null;\n    // Use Optional para um valor padrão.\n  }\n}','Olá, Visitante',/\bOptional\.ofNullable\s*\([\s\S]*\.orElse\s*\(/,['ofNullable aceita null.','orElse fornece o substituto.','Imprima "Olá, " + nome calculado.'],'Um nome reserva espera quando o apelido não chega.'),
    arenaStep('Ordem reversa','A lista 3, 1, 2 deve aparecer em ordem decrescente.','Ordene com uma lambda Comparator e imprima 3, 2, 1 em linhas separadas.', 'import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    List<Integer> notas = new ArrayList<>(Arrays.asList(3, 1, 2));\n    // Use sort com uma lambda e imprima.\n  }\n}','3\n2\n1',/\.sort\s*\(\s*\([\s\S]*->/,['sort recebe um Comparator.','Compare b com a: (a, b) -> Integer.compare(b, a).','Depois percorra a lista ordenada.'],'O comparador escolhe quem vem primeiro na fila.')
  ]},
  {id:'arena-biblioteca',title:'Biblioteca e interfaces',en:'Libraries and UI',summary:'Strings, enum, regex e componentes Swing.',summaryEn:'Strings, enums, regex and Swing components.',icon:'window',color:'#c889ab',steps:[
    arenaStep('Montar mensagem','Uma mensagem é construída em partes.','Use StringBuilder para juntar "Olá", ", " e "Java"; imprima Olá, Java.', 'public class Main {\n  public static void main(String[] args) {\n    StringBuilder texto = new StringBuilder();\n    // Acrescente as partes e imprima.\n  }\n}','Olá, Java',/\bStringBuilder\b[\s\S]*\.append\s*\(/,['Use append três vezes.','A ordem das partes importa.','Imprima texto.toString().'],'O construtor de texto encaixa blocos como peças.'),
    arenaStep('Status com enum','Um pedido pode estar NOVO ou ENVIADO.','Crie enum Status { NOVO, ENVIADO } e imprima Status: ENVIADO usando Status.ENVIADO.', 'enum Status {\n  // Defina NOVO e ENVIADO.\n}\npublic class Main {\n  public static void main(String[] args) {\n    // Imprima o status.\n  }\n}','Status: ENVIADO',/\benum\s+Status\b[\s\S]*\bStatus\.ENVIADO\b/,['Um enum enumera valores permitidos.','Separe NOVO e ENVIADO por vírgula.','Concatene "Status: " com Status.ENVIADO.'],'O enum é uma lista oficial dos estados possíveis.'),
    arenaStep('Validar código','Um código precisa de três letras maiúsculas e dois dígitos.','Use matches("[A-Z]{3}[0-9]{2}") para testar "ABC12" e "abc12"; imprima true e false.', 'public class Main {\n  public static void main(String[] args) {\n    String[] codigos = {"ABC12", "abc12"};\n    // Teste a expressão regular em um laço.\n  }\n}','true\nfalse',/\.matches\s*\(/,['[A-Z]{3} exige três letras maiúsculas.','[0-9]{2} exige dois números.','Percorra os códigos e imprima matches.'],'A expressão regular é um molde para conferir os códigos.'),
    arenaStep('Painel Swing','A interface terá um rótulo e um botão.','Crie JPanel, adicione JLabel e JButton e imprima Componentes: 2 usando getComponentCount(). Não abra JFrame no compilador.', 'import javax.swing.*;\npublic class Main {\n  public static void main(String[] args) {\n    JPanel painel = new JPanel();\n    // Adicione um JLabel e um JButton.\n  }\n}','Componentes: 2',/\bJPanel\b[\s\S]*\bJLabel\b[\s\S]*\bJButton\b[\s\S]*getComponentCount\s*\(/,['Adicione com painel.add(...).','Crie um JLabel e um JButton.','Imprima painel.getComponentCount().'],'O painel é uma mesa que recebe dois componentes.')
  ]}
);
